async function loadOilServicePdfThaiFont() {
    if (typeof document === "undefined" || typeof FontFace === "undefined")
        return;
    let fontAlreadyLoaded = false;
    document.fonts.forEach((font) => {
        if (font.family === "OilServicePdfThai")
            fontAlreadyLoaded = true;
    });
    if (fontAlreadyLoaded)
        return;
    const response = await fetch("/fonts/boss-pdf-thai.ttf");
    if (!response.ok) {
        throw new Error("Unable to load Thai PDF font.");
    }
    const fontData = await response.arrayBuffer();
    const font = new FontFace("OilServicePdfThai", fontData, { style: "normal", weight: "400" });
    await font.load();
    document.fonts.add(font);
    await document.fonts.ready;
}
function binaryStringFromDataUrl(dataUrl) {
    return atob(dataUrl.split(",")[1] ?? "");
}
async function loadCanvasImage(dataUrl) {
    const image = new Image();
    const loaded = new Promise((resolve, reject) => {
        image.onload = () => resolve(image);
        image.onerror = reject;
    });
    image.src = dataUrl;
    return loaded;
}
async function loadOilServicePdfLogo() {
    if (typeof document === "undefined")
        return { dataUrl: null };
    try {
        const response = await fetch("/ees-logo.png");
        if (!response.ok)
            return { dataUrl: null };
        const blob = await response.blob();
        const imageUrl = URL.createObjectURL(blob);
        const image = await new Promise((resolve, reject) => {
            const nextImage = new Image();
            nextImage.onload = () => resolve(nextImage);
            nextImage.onerror = reject;
            nextImage.src = imageUrl;
        });
        const canvas = document.createElement("canvas");
        const targetHeight = 256;
        const targetWidth = Math.max(1, Math.round((image.width / image.height) * targetHeight));
        canvas.width = targetWidth;
        canvas.height = targetHeight;
        const context = canvas.getContext("2d");
        if (!context)
            return { dataUrl: null };
        context.fillStyle = "#ffffff";
        context.fillRect(0, 0, targetWidth, targetHeight);
        context.drawImage(image, 0, 0, targetWidth, targetHeight);
        URL.revokeObjectURL(imageUrl);
        return { dataUrl: canvas.toDataURL("image/png"), height: targetHeight, width: targetWidth };
    }
    catch (error) {
        console.warn("Oil service PDF logo load failed:", error);
        return { dataUrl: null };
    }
}
function buildImagePagesPdf(imagePages, pageSize = { height: 842, width: 595 }) {
    const pageWidth = pageSize.width;
    const pageHeight = pageSize.height;
    const kids = imagePages.map((_, index) => `${3 + index * 3} 0 R`).join(" ");
    const objects = [
        "<< /Type /Catalog /Pages 2 0 R >>",
        `<< /Type /Pages /Kids [${kids}] /Count ${imagePages.length} >>`
    ];
    imagePages.forEach((page, index) => {
        const imageName = `PageImage${index + 1}`;
        const contentStream = `q ${pageWidth} 0 0 ${pageHeight} 0 0 cm /${imageName} Do Q`;
        const pageObjectNumber = 3 + index * 3;
        objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageWidth} ${pageHeight}] /Resources << /XObject << /${imageName} ${pageObjectNumber + 2} 0 R >> >> /Contents ${pageObjectNumber + 1} 0 R >>`, `<< /Length ${contentStream.length} >>\nstream\n${contentStream}\nendstream`, `<< /Type /XObject /Subtype /Image /Width ${page.width} /Height ${page.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${page.data.length} >>\nstream\n${page.data}\nendstream`);
    });
    let pdf = "%PDF-1.4\n";
    const offsets = [0];
    objects.forEach((object, index) => {
        offsets.push(pdf.length);
        pdf += `${index + 1} 0 obj\n${object}\nendobj\n`;
    });
    const xrefOffset = pdf.length;
    pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
    offsets.slice(1).forEach((offset) => {
        pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
    });
    pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
    const bytes = new Uint8Array(pdf.length);
    for (let index = 0; index < pdf.length; index += 1) {
        bytes[index] = pdf.charCodeAt(index) & 0xff;
    }
    return new Blob([bytes], { type: "application/pdf" });
}
function downloadBlob(blob, fileName) {
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = fileName;
    anchor.rel = "noopener";
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}
