        const maxDistance = Math.max(...chartRows.map((row) => row.rawDistance), 1);
        rect(chartX, chartY, chartW, chartH, "#ffffff");
        context.strokeStyle = "#e2e8f0";
        context.lineWidth = 1 * scale;
